import { autoWebViewJs, IPermissionAskResult, Manifest, permissionUtils } from '@droid/android';
import { Log, useTranslation } from '@fanfanlo'
import { Box, Button, Typography } from '@mui/material';
import toast from 'react-hot-toast';
import { ulid } from 'ulid';
export function NotificationOpenButton() {
    const uiLog = new Log(false, 'NotificationOpenButton_ui')
    const { t } = useTranslation('homepage/components/permissions/notification/content');
    function onClick(){
        const permissions = JSON.stringify([
            Manifest.Permission.POST_NOTIFICATIONS
        ])
        console.log('permissions = ', permissions);
        const script = `
        com.fanfanlo.lib.permission.PermissionRequestManager.requestMultiplePermissions(${permissions})
        `
        autoWebViewJs.callScript(script);
        console.log('script = ',script)
    }

    
        function onAskPermissionComplete(stoped:boolean, granted:boolean, result?:IPermissionAskResult){
            uiLog.info('onAskPermissionComplete_fn stoped=', stoped, 'granted=', granted, 'result=', JSON.stringify(result))
            if(!granted){
                toast.error("有未授权的权限，所以无法运行。\n请再次点击按钮运行授权并同意赋权后才能继续执行操作。");
                return;
            }
            readNotifications();
        }
        function readNotifications(){
            
            const script = `
            var s = com.fanfanlo.lib.notification.NotificationReader.readActivePayloads();
            s;
            `;
            console.log('call opensettings')
            const {javaResultString, errMsg} = autoWebViewJs.callScript(script)
            console.log('javaResultString = ', javaResultString, 'errMsg = ', errMsg)
        }
        function askingPermissions(){
            const eventType = ulid();// "a11yNodeSelectActionItem";
            uiLog.info('askingPermissions_fn eventType=', eventType) 
            const res = permissionUtils.askPermissions([
                Manifest.Permission.BIND_NOTIFICATION_LISTENER_SERVICE
            ], eventType, onAskPermissionComplete);
            uiLog.info('askingPermissions_fn res=', res)
            if(res.isGranted){
                onAskPermissionComplete(false, true);
            }
        }

        function openSettings(){
            const script = `
            com.fanfanlo.lib.notification.NotificationReader.openNotificationAccessSettings()
            `;
            console.log('call opensettings')
            autoWebViewJs.callScript(script)
        }
    return (
        <Box>
            <Box>
            <Button onClick={askingPermissions}>{t('NotificationOpenButton.name')}</Button>
            <Typography>{t('NotificationOpenButton.description')}</Typography>
            </Box>
            <Button onClick={openSettings}>
                {t('NotificationOpenButton.setting')}
            </Button>
        </Box>
    )
}