import { autoWebViewJs } from "@droid/android";
import { Log } from "@fanfanlo";
import { Box, Button } from "@mui/material";

const fileLog = new Log(false, "homepage/components/qiyeweixin/testbutton");
export function QiyeWeixinTestButton() {
    const uiLog = fileLog.sub(false, "  QiyeWeixinTestButton_ui");

    async function openApp(){
        const script = `
        com.fanfanlo.lib.intent.IntentFuncs.openApp("com.tencent.wework")`
        autoWebViewJs.callScript(script);
    }
    async function onClick(){
        openApp();
    }
    return (
        <>
            <Box>
                <Button onClick={onClick}>打开企业微信</Button>
            </Box>
        </>
    )
}